const nextPendingWorkerJob = `-- name: NextPendingWorkerJob :one
SELECT id, parent_session_id FROM worker_jobs
WHERE status = 'pending' AND cancel_requested_at IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM worker_prerequisites dependency
    JOIN worker_jobs upstream ON upstream.id = dependency.prerequisite_id
    WHERE dependency.worker_job_id = worker_jobs.id
      AND (upstream.status != 'complete'
        OR COALESCE(json_extract(upstream.result_json, '$.status'), '') NOT IN ('complete', 'open')
        OR (json_extract(upstream.scope_json, '$.mode') = 'write' AND COALESCE(upstream.merge_status, '') != 'merged'))
  )
  AND execution_target = ?1
  AND (?2 = '' OR project_id = ?2)
ORDER BY created_at, id LIMIT 1
`

type NextPendingWorkerJobParams struct {
	ExecutionTarget string      `json:"execution_target"`
	ProjectID       interface{} `json:"project_id"`
}

type NextPendingWorkerJobRow struct {
	ID              string         `json:"id"`
	ParentSessionID sql.NullString `json:"parent_session_id"`
}

func (q *Queries) NextPendingWorkerJob(ctx context.Context, arg NextPendingWorkerJobParams) (NextPendingWorkerJobRow, error) {
	row := q.db.QueryRowContext(ctx, nextPendingWorkerJob, arg.ExecutionTarget, arg.ProjectID)
	var i NextPendingWorkerJobRow
	err := row.Scan(&i.ID, &i.ParentSessionID)
	return i, err
}

