const workerPrerequisiteStates = `-- name: WorkerPrerequisiteStates :many
SELECT upstream.id, upstream.status, upstream.scope_json, upstream.result_json, upstream.merge_status
FROM worker_prerequisites dependency
JOIN worker_jobs upstream ON upstream.id = dependency.prerequisite_id
WHERE dependency.worker_job_id = ? ORDER BY upstream.id
`

type WorkerPrerequisiteStatesRow struct {
	ID          string         `json:"id"`
	Status      string         `json:"status"`
	ScopeJson   sql.NullString `json:"scope_json"`
	ResultJson  sql.NullString `json:"result_json"`
	MergeStatus sql.NullString `json:"merge_status"`
}

func (q *Queries) WorkerPrerequisiteStates(ctx context.Context, workerJobID string) ([]WorkerPrerequisiteStatesRow, error) {
	rows, err := q.db.QueryContext(ctx, workerPrerequisiteStates, workerJobID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkerPrerequisiteStatesRow
	for rows.Next() {
		var i WorkerPrerequisiteStatesRow
		if err := rows.Scan(
			&i.ID,
			&i.Status,
			&i.ScopeJson,
			&i.ResultJson,
			&i.MergeStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
